CREATE OR REPLACE FUNCTION public.is_user_visible(target_user_id uuid) RETURNS boolean AS  BEGIN IF target_user_id = auth.uid() THEN RETURN true; END IF; IF current_setting('request.jwt.claims', true)::json- = 'service_role' THEN RETURN true; END IF; IF EXISTS (SELECT 1 FROM public.friendships WHERE (requester_id = auth.uid() AND addressee_id = target_user_id) OR (addressee_id = auth.uid() AND requester_id = target_user_id)) THEN RETURN true; END IF; IF EXISTS (SELECT 1 FROM public.conversation_members cm1 JOIN public.conversation_members cm2 ON cm1.conversation_id = cm2.conversation_id WHERE cm1.user_id = auth.uid() AND cm2.user_id = target_user_id) THEN RETURN true; END IF; IF EXISTS (SELECT 1 FROM public.event_team_players etp1 JOIN public.event_team_players etp2 ON etp1.event_registration_id = etp2.event_registration_id WHERE etp1.user_id = auth.uid() AND etp2.user_id = target_user_id) THEN RETURN true; END IF; RETURN false; END;  LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;  
